import{_ as e,o,c as n,a1 as a}from"./chunks/framework.DQ_lpCRI.js";const u=JSON.parse('{"title":"Non-App Device Guide","description":"","frontmatter":{},"headers":[],"relativePath":"guide/non-app-devices.md","filePath":"guide/non-app-devices.md"}'),i={name:"guide/non-app-devices.md"};function s(r,t,l,p,h,c){return o(),n("div",null,[...t[0]||(t[0]=[a(`<h1 id="non-app-device-guide" tabindex="-1">Non-App Device Guide <a class="header-anchor" href="#non-app-device-guide" aria-label="Permalink to &quot;Non-App Device Guide&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Devices that cannot run the Android app (game consoles, Macs, Smart TVs) can still use the bypassed connection through <strong>Windows Internet Connection Sharing (ICS)</strong>.</p><p>The setup requires:</p><ol><li>A phone running <strong>Host mode</strong> (the hotspot)</li><li>A Windows laptop running the <strong>Windows Client</strong> in VPN mode</li><li>The target device connects to the laptop&#39;s mobile hotspot</li></ol><hr><h2 id="setup-diagram" tabindex="-1">Setup Diagram <a class="header-anchor" href="#setup-diagram" aria-label="Permalink to &quot;Setup Diagram&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Phone (Host Mode)]</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>   Wi-Fi Direct</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>[Windows Laptop (VPN + Mobile Hotspot)]</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>   Wi-Fi Hotspot</span></span>
<span class="line"><span>       |</span></span>
<span class="line"><span>[PS5 / Xbox / Switch / Mac / TV]</span></span></code></pre></div><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A phone with the app running in <strong>Host mode</strong></li><li>A <strong>Windows laptop</strong> (10 or 11, 64-bit) with Wi-Fi</li><li>The <strong>target device</strong> you want to connect</li></ul><hr><h2 id="step-by-step-setup" tabindex="-1">Step-by-Step Setup <a class="header-anchor" href="#step-by-step-setup" aria-label="Permalink to &quot;Step-by-Step Setup&quot;">​</a></h2><h3 id="step-1-phone-setup" tabindex="-1">Step 1: Phone Setup <a class="header-anchor" href="#step-1-phone-setup" aria-label="Permalink to &quot;Step 1: Phone Setup&quot;">​</a></h3><ol><li>Open the app on your phone.</li><li>Switch to <strong>HOST</strong> tab.</li><li>Tap <strong>Start Host</strong>.</li><li>Note the connection details (SSID, password, proxy IP, port).</li></ol><h3 id="step-2-laptop-setup" tabindex="-1">Step 2: Laptop Setup <a class="header-anchor" href="#step-2-laptop-setup" aria-label="Permalink to &quot;Step 2: Laptop Setup&quot;">​</a></h3><ol><li>Connect your laptop to the phone&#39;s Wi-Fi Direct: <strong>DIRECT-HotspotBypass</strong> (password: <code>87654321</code>).</li><li>Launch the <strong>Windows Client</strong> and start the VPN (see <a href="/Hotspot-Bypass-VPN-Unlimited-Hotspot/guide/windows">Windows Guide</a>).</li><li>Once connected, go to <strong>Settings → Network &amp; Internet → Mobile hotspot</strong>.</li><li>Turn on <strong>Mobile hotspot</strong>.</li></ol><h3 id="step-3-configure-ics" tabindex="-1">Step 3: Configure ICS <a class="header-anchor" href="#step-3-configure-ics" aria-label="Permalink to &quot;Step 3: Configure ICS&quot;">​</a></h3><ol><li>Open <strong>Control Panel → Network and Sharing Center → Change adapter settings</strong>.</li><li>Right-click the <strong>LaptopProxyVPN</strong> TUN adapter → <strong>Properties</strong>.</li><li>Go to the <strong>Sharing</strong> tab.</li><li>Check <strong>Allow other network users to connect through this computer&#39;s Internet connection</strong>.</li><li>In the dropdown, select your mobile hotspot adapter (usually &quot;Local Area Connection* ##&quot; or similar).</li><li>Click <strong>OK</strong>.</li></ol><h3 id="step-4-connect-your-device" tabindex="-1">Step 4: Connect Your Device <a class="header-anchor" href="#step-4-connect-your-device" aria-label="Permalink to &quot;Step 4: Connect Your Device&quot;">​</a></h3><ol><li>On your game console / Mac / TV, open Wi-Fi settings.</li><li>Find and connect to the laptop&#39;s mobile hotspot network.</li><li>The device should now have internet access through the bypassed connection.</li></ol><hr><h2 id="per-device-notes" tabindex="-1">Per-Device Notes <a class="header-anchor" href="#per-device-notes" aria-label="Permalink to &quot;Per-Device Notes&quot;">​</a></h2><h3 id="playstation-5-playstation-4" tabindex="-1">PlayStation 5 / PlayStation 4 <a class="header-anchor" href="#playstation-5-playstation-4" aria-label="Permalink to &quot;PlayStation 5 / PlayStation 4&quot;">​</a></h3><ul><li>Go to <strong>Settings → Network → Settings → Set Up Internet Connection</strong></li><li>Select <strong>Use Wi-Fi</strong> → choose the laptop&#39;s hotspot</li><li>No proxy configuration needed — ICS handles everything</li><li>Test the connection in <strong>Settings → Network → Connection Status</strong></li></ul><h3 id="xbox-series-x-s-xbox-one" tabindex="-1">Xbox Series X|S / Xbox One <a class="header-anchor" href="#xbox-series-x-s-xbox-one" aria-label="Permalink to &quot;Xbox Series X|S / Xbox One&quot;">​</a></h3><ul><li>Go to <strong>Settings → General → Network settings → Set up wireless network</strong></li><li>Select the laptop&#39;s hotspot</li><li>Go to <strong>Test network connection</strong> to verify</li></ul><h3 id="nintendo-switch" tabindex="-1">Nintendo Switch <a class="header-anchor" href="#nintendo-switch" aria-label="Permalink to &quot;Nintendo Switch&quot;">​</a></h3><ul><li>Go to <strong>System Settings → Internet → Internet Settings</strong></li><li>Select the laptop&#39;s hotspot</li><li>Test the connection</li></ul><h3 id="macbook" tabindex="-1">MacBook <a class="header-anchor" href="#macbook" aria-label="Permalink to &quot;MacBook&quot;">​</a></h3><ul><li>Connect to the laptop&#39;s hotspot via Wi-Fi</li><li>No additional configuration needed</li><li>Ideal for gaming, browsing, and streaming</li></ul><h3 id="smart-tv" tabindex="-1">Smart TV <a class="header-anchor" href="#smart-tv" aria-label="Permalink to &quot;Smart TV&quot;">​</a></h3><ul><li>Open <strong>Network Settings</strong> → <strong>Wi-Fi</strong></li><li>Select the laptop&#39;s hotspot</li><li>Works for streaming apps (Netflix, YouTube, etc.) and web browsing</li></ul><hr><h2 id="performance-tips" tabindex="-1">Performance Tips <a class="header-anchor" href="#performance-tips" aria-label="Permalink to &quot;Performance Tips&quot;">​</a></h2><ul><li><strong>5GHz band</strong> — Set the phone to 5GHz Wi-Fi Direct band for lower latency</li><li><strong>Proximity</strong> — Keep the phone and laptop within 10 meters for best signal</li><li><strong>Wired bridge</strong> — For lowest latency, connect the laptop to the console via Ethernet instead of Wi-Fi hotspot</li><li><strong>Close other apps</strong> — Reduce bandwidth usage on the phone for better gaming performance</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>Solution</th></tr></thead><tbody><tr><td>Device connects but no internet</td><td>Check ICS configuration. Restart the mobile hotspot.</td></tr><tr><td>High latency / lag</td><td>Switch phone to 5GHz. Move devices closer together.</td></tr><tr><td>Hotspot not appearing</td><td>Make sure Windows Mobile Hotspot is supported on your laptop.</td></tr><tr><td>VPN disconnects when hotspot is turned on</td><td>Some Wi-Fi adapters can&#39;t handle both. Try a USB Wi-Fi adapter for the hotspot.</td></tr><tr><td>Console can&#39;t find the hotspot</td><td>Set the hotspot to 2.4GHz band in Windows settings.</td></tr></tbody></table>`,39)])])}const g=e(i,[["render",s]]);export{u as __pageData,g as default};
